func trigger_rust_text_editing_delta(
    _ sessionId: UInt64,
    _ revision: UInt64,
    _ replaceStart: Int,
    _ replaceEnd: Int,
    _ utf8Ptr: UnsafePointer<UInt8>?,
    _ utf8Len: Int,
